import sys
import xml.etree.ElementTree as ET
import subprocess
import threading
import time
from queue import Queue
from collections import defaultdict

def parse_config(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        max_parallel = int(root.attrib.get('max_parallel', 1))
        min_interval_ms = int(root.attrib.get('min_interval_ms', 0))
        tasks = {}

        for task_elem in root.findall('task'):
            task_id = task_elem.attrib['id']
            command = task_elem.find('command').text
            tasks[task_id] = command

        return max_parallel, min_interval_ms, tasks
    except Exception as e:
        print("CONFIG_ERROR", file=sys.stderr)
        sys.exit(2)

def execute_task(task_id, command, tasks, max_parallel, min_interval_ms, output_queue):
    try:
        start_time = time.time()
        result = subprocess.run(
            command,
            shell=True,
            text=True,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
        elapsed_ms = int((time.time() - start_time) * 1000)

        if elapsed_ms < min_interval_ms:
            time.sleep((min_interval_ms - elapsed_ms) / 1000)

        stdout = result.stdout.replace('\n', ' ')
        stderr = result.stderr.replace('\n', ' ')
        output_queue.put(f"{task_id}\t{result.returncode}\t{stdout}\t{stderr}")
    except subprocess.CalledProcessError as e:
        output_queue.put(f"{task_id}\tUNAVAILABLE")
    except Exception:
        output_queue.put(f"{task_id}\tUNAVAILABLE")

def process_tasks(max_parallel, min_interval_ms, tasks, input_queue):
    running = 0
    last_start_time = 0

    while True:
        if running < max_parallel:
            if not input_queue.empty():
                task_id = input_queue.get()
                if task_id in tasks:
                    command = tasks[task_id]
                    threading.Thread(
                        target=execute_task,
                        args=(task_id, command, tasks, max_parallel, min_interval_ms, output_queue)
                    ).start()
                    running += 1
                    last_start_time = time.time()
            else:
                time.sleep(0.1)
        else:
            current_time = time.time()
            if current_time - last_start_time >= min_interval_ms / 1000:
                if not input_queue.empty():
                    task_id = input_queue.get()
                    if task_id in tasks:
                        command = tasks[task_id]
                        threading.Thread(
                            target=execute_task,
                            args=(task_id, command, tasks, max_parallel, min_interval_ms, output_queue)
                        ).start()
                        running += 1
                        last_start_time = current_time
                else:
                    time.sleep(0.1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python dispatcher.py <config_file>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    max_parallel, min_interval_ms, tasks = parse_config(xml_path)

    input_queue = Queue()
    output_queue = Queue()

    for line in sys.stdin:
        line = line.strip()
        if line:
            input_queue.put(line)

    process_tasks(max_parallel, min_interval_ms, tasks, input_queue)

    while not output_queue.empty():
        print(output_queue.get())

if __name__ == "__main__":
    main()
